"""Rendering the reference of `global.lua`'s helpers (research/script-helpers.yaml) into its page beside the binding
pages, docs/references/bindings/helpers.md: the conventions, the groups, the globals, then a section per helper."""

from __future__ import annotations

from coney_tools.natives import EVIDENCE, Masterlist
from coney_tools.natives_render import bullet, cell, wrap
from coney_tools.script_helpers import GROUPS, HELPERS_SCRIPT, Helper, HelperList

GENERATED = (
    "<!-- Generated by `coney-tools bindings render` from research/script-helpers.yaml. Do not edit by hand. -->"
)


def _code(name: str) -> str:
    """A name in code style."""
    return f"`{name}`"


def _native_link(name: str, masterlist: Masterlist) -> str:
    """A binding's name, linked to its section when the masterlist has it."""
    binding = next((b for b in masterlist.bindings if b.name == name), None)
    return f"[`{name}`]({binding.category}.md#{binding.anchor})" if binding else _code(name)


def _helper_link(name: str, by_name: dict[str, Helper]) -> str:
    """A helper's name, linked to its section when the page has one."""
    return f"[`{name}`](#{by_name[name].anchor})" if name in by_name else _code(name)


def _evidence(helper: Helper) -> str:
    """The evidence line: the level and the script locator of the helper's function."""
    level = EVIDENCE[helper.evidence]
    return f"{level} at `{HELPERS_SCRIPT}:f{helper.scan.function}`" if helper.scan else level


def _plural(count: int, word: str) -> str:
    """`count` and `word`, with an s when it is not one."""
    return f"{count} {word}{'' if count == 1 else 's'}"


def helper_section(helper: Helper, by_name: dict[str, Helper], callers: list[str], masterlist: Masterlist) -> list[str]:
    """The section of one helper: its signature, description and facts."""
    out = [f"### {helper.name} {{#{helper.anchor}}}", "", "```lua", f"{helper.name}({', '.join(helper.params)})", "```"]
    out += ["", *wrap(helper.description), ""]
    if helper.notes:
        out += [*wrap(f"**Notes.** {helper.notes}"), ""]
    facts = [f"**Evidence:** {_evidence(helper)}"]
    scan = helper.scan
    if scan is not None:
        if scan.natives:
            facts.append("**Natives:** " + ", ".join(_native_link(n, masterlist) for n in scan.natives))
        if scan.helpers:
            facts.append("**Helpers it calls or names:** " + ", ".join(_helper_link(n, by_name) for n in scan.helpers))
        if callers:
            facts.append("**Called by helpers:** " + ", ".join(_helper_link(n, by_name) for n in callers))
        used = (
            f"**Called by** {_plural(scan.scripts, 'script')} ({_plural(scan.calls, 'call')})"
            if scan.scripts
            else "**Called by** no other script on the disc"
        )
        when = []
        if scan.at_load:
            when.append("runs while `global.lua` loads")
        if scan.registered:
            when.append("registered by `global.lua` as a callback the engine calls by name")
        if scan.deleted_by:
            whom = ", ".join(_helper_link(n, by_name) if n in by_name else n for n in scan.deleted_by)
            when.append(f"deleted by {whom}")
        facts.append(used + ("; " + "; ".join(when) if when else ""))
    return out + [line for fact in facts for line in bullet(fact)] + [""]


def _callers(helpers: list[Helper]) -> dict[str, list[str]]:
    """For each helper, the helpers that call it, in page order."""
    found: dict[str, list[str]] = {h.name: [] for h in helpers}
    for helper in helpers:
        for name in helper.scan.helpers if helper.scan else ():
            if name in found and helper.name not in found[name]:
                found[name].append(helper.name)
    return found


def _ordered(helpers: list[Helper]) -> list[Helper]:
    """The helpers in page order: by group, then in the order the chunk defines them."""
    groups = list(GROUPS)
    return sorted(helpers, key=lambda h: (groups.index(h.group), h.scan.function if h.scan else 0, h.name))


def page(data: HelperList, masterlist: Masterlist) -> str:
    """The page of every helper and global."""
    helpers = _ordered(data.helpers)
    by_name = {h.name: h for h in helpers}
    callers = _callers(helpers)
    called = sum(1 for h in helpers if h.scan and h.scan.scripts)
    sha1 = f" (SHA1 `{data.chunk_sha1}`)" if data.chunk_sha1 else ""
    out = [
        GENERATED,
        "",
        "# global.lua helpers",
        "",
        f"Verified against: `{HELPERS_SCRIPT}` of the NTSC-U disc{sha1}.",
        "",
    ]
    out += wrap(
        f"Before a level's script runs, the game state runs `{HELPERS_SCRIPT}` in the same Lua 4.0 state"
        " ([Scripts (Lua)](../../research/scripting.md)), and the level scripts build on what it defines: this page"
        f" lists its {len(helpers)} functions (the **helpers**) and the {len(data.globals)} globals it sets that"
        f" other scripts read. {called} of the helpers are called by the game's other scripts. Each entry gives our"
        " names for the parameters, what the helper does in our own words, the natives (bindings) and other helpers"
        " it calls, how sure we are, and how many of the disc's scripts call it. It is the API a"
        " [mission mod](../../guides/studio/mission-mods.md) builds on beside the [bindings](index.md), and the"
        " source of the completions Coney Studio's [script editor](../../guides/studio/script-editor.md) offers in"
        " game-state files."
    )
    out.append("")
    out += wrap(
        "**Bare globals, no namespace.** The helpers are plain globals of the game state, called by name"
        " (`ActivateWarriors()`, not `Global.ActivateWarriors()`), as the original's scripts call them; a patched"
        " script calls them the same way, and a namespace would break every call the unpatched scripts make. They"
        " exist only in the game state's Lua 4.0: Coney's own Lua 5.4 scripts cannot call them. A helper that"
        " `global.lua` deletes after running (the load-time setup functions, and the groups a level switches off"
        " with `SuperClean`, `NoScenes` or `ObjectiveKill`) is gone once that has run, and calling it then is a"
        " script error, which the game ignores silently."
    )
    out.append("")
    out += wrap(
        "Everything here is generated by `coney-tools bindings render` from `research/script-helpers.yaml` (schema:"
        " [The research data](../../guides/research-data.md#script-helpers)); `coney-tools bindings scan-helpers`"
        " fills its counts from your disc. Only names and counts are read from the disc, never the script's text."
        " The evidence of each entry cites the helper's function in the chunk as a script locator"
        " (`global.lua:fN`: function prototype N). The calls are counted as the bindings'"
        " [usage counts](index.md#usage) are: each read of a name (a native or helper fetched to be called, or a"
        " helper's name passed as a callback) is one, so a call in a loop counts once and one in a branch that never"
        " runs counts too."
    )
    out += ["", "## Groups", "", "| Group | Helpers | Called by other scripts |", "| --- | --- | --- |"]
    for group, (title, scope) in GROUPS.items():
        rows = [h for h in helpers if h.group == group]
        if rows:
            used = sum(1 for h in rows if h.scan and h.scan.scripts)
            out.append(f"| [{title}](#{group}): {scope} | {len(rows)} | {used} |")
    out += ["", "## Globals {#globals}", ""]
    out += wrap(
        f"The globals `{HELPERS_SCRIPT}` sets, or a helper it runs while loading sets, that other scripts read:"
        " the kind of value each ends with, how many scripts read it, and what it is for. A global that"
        f" `{HELPERS_SCRIPT}` clears at the end is read by scripts that set their own."
    )
    out += ["", "| Global | Value | Scripts | Meaning |", "| --- | --- | --- | --- |"]
    groups = list(GROUPS)
    for variable in sorted(data.globals, key=lambda g: (groups.index(g.group), g.name.lower())):
        scan = variable.scan
        value = "-" if scan is None else scan.value
        if scan is not None and scan.cleared:
            value += f" (cleared at the end of `{HELPERS_SCRIPT}`)"
        meaning = variable.description
        if variable.evidence != "confirmed-code":
            meaning += f" ({EVIDENCE[variable.evidence]})"
        out.append(f"| `{variable.name}` | {value} | {scan.scripts if scan else '-'} | {cell(meaning)} |")
    for group, (title, scope) in GROUPS.items():
        rows = [h for h in helpers if h.group == group]
        if not rows:
            continue
        while out and not out[-1]:
            out.pop()
        out += ["", f"## {title} {{#{group}}}", "", *wrap(f"Helpers for {scope}."), ""]
        for helper in rows:
            out += helper_section(helper, by_name, callers[helper.name], masterlist)
    return "\n".join(out).rstrip("\n") + "\n"
